INSERT INTO guides
  (slug,category_id,category_label,title,description,read_time,updated_label,image_url,image_key,content_json,sort_order,is_published)
VALUES
  ('how-to-choose-smart-pet-door',(SELECT id FROM categories WHERE slug='smart-pet-doors'),'Smart Pet Doors','How to choose a smart pet door','Compare microchip recognition, opening dimensions, weather sealing, manual override, and what happens when power or connectivity fails.','7 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='smart-pet-doors'),'guides/how-to-choose-smart-pet-door.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Start with the opening','body','Measure the flap, wall or door thickness, and the pet that must pass through before comparing apps or schedules.'),JSON_OBJECT('title','Plan for offline moments','body','A smart door still needs a safe manual mode when batteries, hubs, Wi-Fi, or the cloud are unavailable.'),JSON_OBJECT('title','Check selective access','body','Confirm which pets can be registered, how recognition works, and whether unwanted animals can push through.'),JSON_OBJECT('title','Can a smart pet door replace supervision?','body','No. It manages access but does not replace checking that a pet is safe, healthy, and indoors when expected.'))),14,TRUE),
  ('how-to-interpret-pet-health-monitor-data',(SELECT id FROM categories WHERE slug='pet-health-monitors'),'Pet Health Monitors','How to interpret pet health monitor data','Use activity, sleep, temperature, weight, and location trends as prompts for better observation—not as an automated diagnosis.','8 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='pet-health-monitors'),'guides/how-to-interpret-pet-health-monitor-data.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Build a baseline','body','Collect several days of normal readings before treating a change as meaningful.'),JSON_OBJECT('title','Separate signals from conclusions','body','A device can report a trend without explaining its cause. Pair unusual readings with appetite, behavior, breathing, mobility, and litter-box observations.'),JSON_OBJECT('title','Know when to call','body','Contact a veterinarian for concerning symptoms or sustained changes regardless of what the app reports.'),JSON_OBJECT('title','Can a collar diagnose illness?','body','No. Consumer monitors can support observation and conversations with a veterinarian, but they are not a diagnosis.'))),15,TRUE)
