SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),category_label=VALUES(category_label),title=VALUES(title),description=VALUES(description),read_time=VALUES(read_time),updated_label=VALUES(updated_label),image_url=VALUES(image_url),image_key=VALUES(image_key),content_json=VALUES(content_json),sort_order=VALUES(sort_order),is_published=TRUE;
